using System;using LWS.TruckFieldGoal;
namespace LWS.TruckFieldGoal.Editor {public static class FieldGoalFixtures {public static void Run(){int checks=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Field goal rule fixture: "+label);checks++;};var r=new FieldGoalRules();r.Reset(4);check(!r.Advance(),"unresolved attempt cannot advance");for(int round=1;round<=5;round++){check(r.Round==round&&r.Current==(round-1)%4,"rotating first shooter");for(int shot=0;shot<4;shot++){int owner=r.Current;check(r.Lock(owner==0),"one delivery locks");check(!r.Lock(true),"duplicate contact cannot score");check(r.attempts[owner]==round,"equal attempts per round");r.Advance();}}check(r.Complete&&r.Winner==0&&Array.TrueForAll(r.attempts,x=>x==5)&&r.goals[0]==5,"complete five-attempt match");check(!r.Lock(true)&&!r.Advance(),"results lock");r.Reset(3);for(int i=0;i<15;i++){r.Lock(false);r.Advance();}check(r.Round==6&&!r.Complete&&r.Eligible==7,"tied leaders enter extra launch");for(int i=0;i<3;i++){r.Lock(r.Current==1);r.Advance();if(i<2)check(!r.Complete,"extra round preserves equal opportunity");}check(r.Winner==1&&Array.TrueForAll(new[]{r.attempts[0],r.attempts[1],r.attempts[2]},x=>x==6),"extra round winner after all shoot");r.Reset(4);for(int i=0;i<20;i++){r.Lock(r.Current<2);r.Advance();}check(r.Eligible==3&&r.Round==6,"only tied leaders remain eligible");r.Reset(1,true);for(int i=0;i<12;i++){r.Lock(i%2==0);r.Advance();}check(!r.Complete&&r.attempts[0]==12&&r.goals[0]==6,"solo practice keeps flowing");float t,x,y;check(FieldGoalRules.ForwardGoal(0,6,0,0,5,1000,50,5,3.05f,float.PositiveInfinity,out t,out x,out y)&&t>.049f&&t<.051f,"high-speed legal forward sweep");check(!FieldGoalRules.ForwardGoal(0,6,100,0,6,0,50,5,3.05f,float.PositiveInfinity,out t,out x,out y),"backward crossing rejected");check(!FieldGoalRules.ForwardGoal(0,6,0,12,6,100,50,5,3.05f,float.PositiveInfinity,out t,out x,out y),"wide crossing rejected");check(!FieldGoalRules.ForwardGoal(0,2,0,0,2,100,50,5,3.05f,float.PositiveInfinity,out t,out x,out y),"below crossbar rejected");check(!FieldGoalRules.ForwardGoal(0,6,0,0,6,100,50,5,3.05f,.4f,out t,out x,out y),"ground before plane rejects goal");check(FieldGoalRules.ForwardGoal(0,6,0,0,6,100,50,5,3.05f,.6f,out t,out x,out y),"plane before ground remains legal");System.IO.Directory.CreateDirectory("Logs/TruckSports/SevenSports");System.IO.File.WriteAllText("Logs/TruckSports/SevenSports/field-goal-rules-result.txt","PASS "+checks+" focused pure rules checks; physical acceptance is separate");UnityEngine.Debug.Log("FIELD_GOAL_RULES_PASS "+checks);}}

}
